python3 -c "
import json
with open('/app/resources/treasury_bulletin_2012_06.json') as f:
    data = json.load(f)

# Find tables with employment data
def search_nested(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'employment' in str(k).lower() and 'general' in str(k).lower():
                print(f'Found at {path}.{k}: {v}')
            search_nested(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search_nested(item, f'{path}[{i}]')

search_nested(data)
"

python3 -c "
import json
with open('/app/resources/treasury_bulletin_2012_06.json') as f:
    data = json.load(f)

# Look at all keys in the JSON to understand structure
def find_keys(obj, target):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if target.lower() in str(k).lower():
                print(f'Key: {k}')
                print(f'Value: {v}')
            find_keys(v, target)
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_keys(item, target)

find_keys(data, 'employment')
"

python3 -c "
import json
with open('/app/resources/treasury_bulletin_2012_06.json') as f:
    data = json.load(f)

# Search for any string containing 'employment'
def search_all(obj, depth=0):
    if depth > 5:
        return
    if isinstance(obj, str) and 'employment' in obj.lower():
        print(f'Found: {obj}')
    elif isinstance(obj, dict):
        for k, v in obj.items():
            search_all(v, depth+1)
    elif isinstance(obj, list):
        for item in obj:
            search_all(item, depth+1)

search_all(data)
"
